import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class Main{
 static String u(int n){return new String[]{"cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve"}[n];}
 static String c(int n){Map<Integer,String>e=Map.ofEntries(Map.entry(10,"diez"),Map.entry(11,"once"),Map.entry(12,"doce"),Map.entry(13,"trece"),Map.entry(14,"catorce"),Map.entry(15,"quince"),Map.entry(16,"dieciseis"),Map.entry(17,"diecisiete"),Map.entry(18,"dieciocho"),Map.entry(19,"diecinueve"),Map.entry(20,"veinte"),Map.entry(21,"veintiuno"),Map.entry(22,"veintidos"),Map.entry(23,"veintitres"),Map.entry(24,"veinticuatro"),Map.entry(25,"veinticinco"),Map.entry(26,"veintiseis"),Map.entry(27,"veintisiete"),Map.entry(28,"veintiocho"),Map.entry(29,"veintinueve"));Map<Integer,String>d=Map.of(30,"treinta",40,"cuarenta",50,"cincuenta",60,"sesenta",70,"setenta",80,"ochenta",90,"noventa");Map<Integer,String>ci=Map.of(100,"cien",200,"doscientos",300,"trescientos",400,"cuatrocientos",500,"quinientos",600,"seiscientos",700,"setecientos",800,"ochocientos",900,"novecientos");if(n<10)return u(n);if(e.containsKey(n))return e.get(n);if(n<100){int de=n/10*10,un=n%10;return un>0?d.get(de)+" y "+u(un):d.get(de);}if(ci.containsKey(n))return ci.get(n);int ce=n/100*100,r=n%100;return (ce==100?"ciento":ci.get(ce))+" "+c(r);}
 static String num(int n){if(n==0)return"cero";if(n<0)return"menos "+num(-n);if(n<1000)return c(n);if(n<1000000){int m=n/1000,r=n%1000;String p=m==1?"mil":num(m)+" mil";return r>0?p+" "+c(r):p;}int mi=n/1000000,r=n%1000000;String p=mi==1?"un millon":num(mi)+" millones";return r>0?p+" "+num(r):p;}
 public static void main(String[]args)throws Exception{HttpServer s=HttpServer.create(new InetSocketAddress(3000),0);s.createContext("/",ex->{String q=ex.getRequestURI().getQuery();int n=10;if(q!=null&&q.startsWith("n="))n=Integer.parseInt(q.substring(2));byte[]b=num(n).getBytes(StandardCharsets.UTF_8);ex.sendResponseHeaders(200,b.length);ex.getResponseBody().write(b);ex.close();});s.start();System.out.println("Servidor en http://localhost:3000/?n=10");}}
